<?php require 'config.php';require_login();$title='Employees';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(isset($_POST['delete'])){$q=$pdo->prepare('DELETE FROM employees WHERE id=?');$q->execute([(int)$_POST['delete']]);flash('Employee removed.');go('employees.php');}
$q=$pdo->prepare('INSERT INTO employees(name,email,phone,position,department_id,hire_date) VALUES(?,?,?,?,?,?)');$q->execute([trim($_POST['name']),trim($_POST['email']),trim($_POST['phone']),trim($_POST['position']),(int)($_POST['department_id']?:0)?:null,$_POST['hire_date']]);flash('Employee added successfully.');go('employees.php');}
$depts=$pdo->query('SELECT id,name FROM departments ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT e.*,d.name department FROM employees e LEFT JOIN departments d ON d.id=e.department_id ORDER BY e.id DESC')->fetchAll();require 'partials/header.php';?>
<div class="pagehead"><div><div class="eyebrow">PEOPLE</div><h1>Employees</h1><p class="sub">Manage employee profiles and team information.</p></div></div>
<div class="card"><div class="cardhead"><h2>Add an employee</h2></div><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="formgrid"><div class="field"><label>Full name</label><input name="name" required></div><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Phone</label><input name="phone"></div><div class="field"><label>Job title</label><input name="position" required placeholder="e.g. Accounts Executive"></div><div class="field"><label>Department</label><select name="department_id"><option value="">Unassigned</option><?php foreach($depts as $d):?><option value="<?=$d['id']?>"><?=h($d['name'])?></option><?php endforeach?></select></div><div class="field"><label>Joining date</label><input type="date" name="hire_date"></div></div><div class="actions"><button class="btn">＋ Save employee</button></div></form></div>
<div class="card"><div class="cardhead"><h2>Employee directory <span class="muted">(<?=count($rows)?>)</span></h2></div><div class="tablewrap"><table><thead><tr><th>Employee</th><th>Position</th><th>Department</th><th>Phone</th><th>Joined</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=h($r['name'])?></strong><br><span class="muted"><?=h($r['email'])?></span></td><td><?=h($r['position'])?></td><td><?=h($r['department']??'—')?></td><td><?=h($r['phone'])?></td><td><?=h($r['hire_date'])?></td><td><form method="post" onsubmit="return confirm('Delete this employee?')"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><button class="btn danger small" name="delete" value="<?=$r['id']?>">Delete</button></form></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="6" class="empty">No employee records yet.</td></tr><?php endif?></tbody></table></div></div>
<?php require 'partials/footer.php';?>
